#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# parse_data_distribution ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`parse_data_distribution()` works with correct inputs", {
  #' @description Test that a lognormal distribution string is parsed into a flat list of its family, link, and parameters.
  expect_equal(
    parse_data_distribution(
      "~ dlnorm(meanlog = log_landings_expected, sdlog = 0.00999975001354021)"
    ),
    list(
      family = "dlnorm",
      link = quote(log_landings_expected),
      meanlog = quote(log_landings_expected),
      sdlog = 0.00999975001354021
    )
  )

  #' @description Test that whitespace is not required between the formula operator and a normal distribution call.
  expect_equal(
    parse_data_distribution("~dnorm(mean = landings_expected, sd = 0.1)"),
    list(
      family = "dnorm",
      link = quote(landings_expected),
      mean = quote(landings_expected),
      sd = 0.1
    )
  )

  #' @description Test that calls and single-element expressions are accepted without first converting them to strings.
  expect_equal(
    parse_data_distribution(quote(~ dnorm(mean = index_expected, sd = 1))),
    parse_data_distribution(expression(~ dnorm(mean = index_expected, sd = 1)))
  )
})

## Edge handling ----
test_that("`parse_data_distribution()` returns correct outputs for edge cases", {
  #' @description Test that a missing distribution specification returns an `NA` family while preserving row alignment.
  expect_equal(
    parse_data_distribution(NA_character_)[1],
    list(family = NA_character_)
  )
})

## Error handling ----
test_that("`parse_data_distribution()` returns correct error messages", {
  #' @description Test that unsupported input types return an informative error.
  expect_error(
    parse_data_distribution(list("~dnorm(mean = x, sd = 1)")),
    "must be a string, expression, call, or formula",
    fixed = TRUE
  )

  #' @description Test that input without the formula operator returns an informative error.
  expect_error(
    parse_data_distribution("dnorm(mean = x, sd = 1)"),
    "Expression must be a distribution call",
    fixed = TRUE
  )

  #' @description Test that two-sided formulas are rejected for data distribution specifications.
  expect_error(
    parse_data_distribution("landings ~ dnorm(mean = x, sd = 1)"),
    "Two-sided formulas are not allowed",
    fixed = TRUE
  )

  #' @description Test that the family-specific central parameter must be present.
  expect_error(
    parse_data_distribution("~dnorm(sd = 1)"),
    "The central parameter does not exist for dnorm",
    fixed = TRUE
  )

  #' @description Test that distribution arguments must be formal arguments of the selected family.
  expect_error(
    parse_data_distribution("~dnorm(mean = x, sd = 1, extra = 2)"),
    "are not formal arguments of the dnorm function",
    fixed = TRUE
  )

  #' @description Test that a normal distribution standard deviation must be positive.
  expect_error(
    parse_data_distribution("~dnorm(mean = x, sd = -0.1)"),
    "`sd` must be positive",
    fixed = TRUE
  )

  #' @description Test that a lognormal distribution log-scale standard deviation must be positive.
  expect_error(
    parse_data_distribution("~dlnorm(meanlog = x, sdlog = 0)"),
    "`sdlog` must be positive",
    fixed = TRUE
  )
})
